 "group": "isTypeAllowedInSection",
 "cases": [
   {
     "input": [
       {"parameter":"type","value":"Type.A"},
       {"parameter":"section","value":"Section.ADDITIONAL"}
     ],
     "expected":"SecurityException",
     "description":"When a SecurityManager denies access to system property dnsjava.harden_unknown_additional, a SecurityException is thrown."
   }
 ]
}

